        TTI_SFPLOADI(4, 0, 0x3f00);
        TTI_SFPSWAP(0, 2, 4, 1);
        TTI_SFPEXMAN(0, 2, 4, 0);
        TTI_SFPEXEXP(0, 2, 2, 0);
        TTI_SFPLOADI(7, 0, 0x419c);
        TTI_SFPLOAD(6, 0, 7, 0x40);
        TTI_SFPSHFT(0, 2, 4, 0);
        TTI_SFPSWAP(0, 7, 1, 1);
        TTI_SFPSETSGN(0, 6, 3, 1);
        TTI_SFPLOADI(2, 1, 0x579e);
        TTI_SFPMOV(0, 1, 5, 2);
        TTI_SFPSWAP(0, 2, 3, 1);
        TTI_SFPMULI(0x3e80, 5, 0);
        TTI_SFPADD(10, 2, 7, 2, 3);
        TTI_SFPMUL(3, 12, 9, 7, 0);
        TTI_SFPMUL(5, 5, 9, 5, 0);
        TTI_SFPMUL(7, 7, 9, 7, 0);
        TTI_SFPSETSGN(0, 1, 0, 0);
        TTI_SFPLOADI(1, 2, 0x2220);
        TTI_SFPLOADI(1, 8, 0x3a35);
        TTI_SFPMULI(0x4b80, 0, 0);
        TTI_SFPSWAP(0, 2, 9, 1);
        TTI_SFPSETSGN(0, 3, 6, 0);
        TTI_SFPLOADI(3, 2, 0x3b90);
        TTI_SFPLOADI(3, 8, 0x3dd3);
        TTI_SFPMUL(0, 6, 9, 0, 0);
        TTI_SFPMAD(5, 1, 3, 6, 0);
        TTI_SFPMAD(7, 1, 3, 3, 0);
        TTI_SFPLOADI(1, 1, 0x22ac);
        TTI_SFPMAD(6, 5, 10, 6, 0);
        TTI_SFPMAD(3, 7, 10, 3, 0);
